import{_ as i,a0 as p,w as u,s as S,ao as e,I as r,a1 as o,A as n,x as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Linux 黑话解释：什么是 FOSS（自由和开源软件）？什么是开源？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux 黑话解释：什么是 FOSS（自由和开源软件）？什么是开源？ | LCTT (202010) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 黑话解释：什么是 FOSS（自由和开源软件）？什么是开源？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 黑话解释：什么是 FOSS（自由和开源软件）？什么是开源？ | LCTT (202010) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20200926 Linux Jargon Buster- What is FOSS (Free and Open Source Software)- What is Open Source","title":"Linux 黑话解释：什么是 FOSS（自由和开源软件）？什么是开源？","tag":"202010","desc":""},"relativePath":"202010/20200926 Linux Jargon Buster- What is FOSS (Free and Open Source Software)- What is Open Source.md","filePath":"[post].md"}'),a={name:"202010/20200926 Linux Jargon Buster- What is FOSS (Free and Open Source Software)- What is Open Source.md"};function f(d,t,m,O,F,x){const l=p("Link");return u(),S("div",null,[t[35]||(t[35]=e('<h1 id="linux-黑话解释-什么是-foss-自由和开源软件-什么是开源" tabindex="-1">Linux 黑话解释：什么是 FOSS（自由和开源软件）？什么是开源？ <a class="header-anchor" href="#linux-黑话解释-什么是-foss-自由和开源软件-什么是开源" aria-label="Permalink to “Linux 黑话解释：什么是 FOSS（自由和开源软件）？什么是开源？”">​</a></h1><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/09/what-is-foss.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>什么是 FOSS？</p><p>在过去，我曾多次被问到这个问题，现在是时候解释一下什么是 Linux 和软件世界中的 FOSS 了。</p><p>这个区别很重要，因为 FOSS 是一个通用的词汇，它可以根据上下文的不同而有不同的含义。在这里，我讨论的是软件中的 FOSS 原则。</p><h3 id="什么是-foss" tabindex="-1">什么是 FOSS？ <a class="header-anchor" href="#什么是-foss" aria-label="Permalink to “什么是 FOSS？”">​</a></h3><p>FOSS 是指<ruby>自由和开放源码软件<rt>Free and Open Source Software</rt></ruby>。这并不意味着软件是免费的。它意味着软件的源代码是开放的，任何人都可以自由使用、研究和修改代码。这个原则允许人们像一个社区一样为软件的开发和改进做出贡献。</p><h4 id="foss-的起源" tabindex="-1">FOSS 的起源 <a class="header-anchor" href="#foss-的起源" aria-label="Permalink to “FOSS 的起源”">​</a></h4><p>在上世纪 60、70 年代，计算机以硬件为主，硬件价格昂贵。它们主要由大学的学者或实验室的研究人员使用。以前有限的软件都是免费的，或者是带有它们的源代码，用户可以根据自己的需要修改源代码。</p><p>在上世纪 70 年代末和 80 年代初，制造商为了不让自己的软件在竞争对手的计算机上运行，停止了分发源代码。</p><p>这种限制性的许可导致了那些习惯和喜欢修改软件的人的不便和不喜。上世纪 80 年代中期，Richard Stallman 发起了<ruby>自由软件运动<rt>Free Software Movement</rt></ruby>。</p>',11)),r("p",null,[o(l,{href:"https://www.gnu.org/philosophy/free-sw.html"},{default:n(()=>[...t[0]||(t[0]=[s("Stallman 指明了一个软件要成为 FOSS 的四个基本自由",-1)])]),_:1}),t[1]||(t[1]=s("。",-1))]),t[36]||(t[36]=r("p",null,[r("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/09/foss-freedoms.jpg?resize=800%2C671&ssl=1",alt:"自由软件自由"})],-1)),t[37]||(t[37]=r("p",null,"为了便于理解，我将它们重新表述：",-1)),t[38]||(t[38]=r("ul",null,[r("li",null,"任何用户应能为任何目的运行软件。"),r("li",null,"用户应能自由查看软件的源代码，如有需要，应允许用户修改代码。"),r("li",null,"用户应能自由地将软件的副本分发给他人。"),r("li",null,"如果用户修改了代码，她/他应该可以自由地将修改后的代码发布给他人。修改后的代码必须开放源代码。")],-1)),r("p",null,[t[3]||(t[3]=s("如果有兴趣，我建议阅读这篇关于 ",-1)),o(l,{href:"https://itsfoss.com/history-of-foss/"},{default:n(()=>[...t[2]||(t[2]=[s("FOSS 的历史",-1)])]),_:1}),t[4]||(t[4]=s("的文章。",-1))]),t[39]||(t[39]=e('<h3 id="foss-中的-free-并不意味着免费" tabindex="-1">FOSS 中的 “Free” 并不意味着免费 <a class="header-anchor" href="#foss-中的-free-并不意味着免费" aria-label="Permalink to “FOSS 中的 “Free” 并不意味着免费”">​</a></h3><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/09/think-free-speech-not-free-beer.jpg?resize=800%2C800&amp;ssl=1" alt=""></p><p>你可能已经注意到了，自由和开源软件中的 “Free” 并不意味着它是免费的，它意味着运行、修改和分发软件的“自由”。</p><p>人们经常错误地认为，FOSS 或开源软件不能有价格标签。这是不正确的。</p><p>大多数 FOSS 都是免费提供的，原因有很多：</p><ul><li>源代码已经向公众开放，所以一些开发者认为没有必要在下载软件时贴上价格标签。</li><li>有些项目是由一些志愿者免费提供的。因此，主要的开发者认为对这么多人免费贡献的东西收费是不道德的。</li><li>有些项目是由较大的企业或非营利组织支持和/或开发的，这些组织会雇佣开发人员在他们的开源项目上工作。</li><li>有些开发者创建开源项目是出于兴趣，或者出于他们对用代码为世界做贡献的热情。对他们来说，下载量、贡献和感谢的话比金钱更重要。</li></ul><p>为了避免强调 “免费”，有些人使用了 FLOSS 这个词（LCTT 译注：有时候也写作 F/LOSS）。FLOSS 是<ruby>自由和开源软件<rt>Free/Libre Open Source Software</rt></ruby>的缩写。单词 Libre（意为自由）与 gartuit/gratis（免费）不同。</p><blockquote><p>“Free” 是言论自由的自由，而不是免费啤酒的免费。</p></blockquote><h3 id="foss-项目如何赚钱" tabindex="-1">FOSS 项目如何赚钱？ <a class="header-anchor" href="#foss-项目如何赚钱" aria-label="Permalink to “FOSS 项目如何赚钱？”">​</a></h3>',9)),r("p",null,[t[6]||(t[6]=s("开源项目不赚钱是一个神话。红帽是第一个达到 10 亿美元大关的开源公司。",-1)),o(l,{href:"https://itsfoss.com/ibm-red-hat-acquisition/"},{default:n(()=>[...t[5]||(t[5]=[s("IBM 以 340 亿美元收购了红帽",-1)])]),_:1}),t[7]||(t[7]=s("。这样的例子有很多。",-1))]),t[40]||(t[40]=r("p",null,"许多开源项目，特别是企业领域的项目，都会提供收费的支持和面向企业的功能。这是红帽、SUSE Linux 和更多此类项目的主要商业模式。",-1)),t[41]||(t[41]=r("p",null,"一些开源项目，如 Discourse、WordPress 等，则提供其软件的托管实例，并收取一定的费用。",-1)),r("p",null,[t[9]||(t[9]=s("许多开源项目，特别是桌面应用程序，依靠捐赠。VLC、GIMP、Inkscape 等这类开源软件就属于这一类。有",-1)),o(l,{href:"https://itsfoss.com/open-source-funding-platforms/"},{default:n(()=>[...t[8]||(t[8]=[s("资助开源项目的方法",-1)])]),_:1}),t[10]||(t[10]=s("，但通常，你会在项目网站上找到捐赠链接。",-1))]),t[42]||(t[42]=e('<p>利用开源软件赚钱可能很难，但也不是完全不可能。</p><h3 id="但我不是程序员-我为什么要关心一个软件是否开源" tabindex="-1">但我不是程序员，我为什么要关心一个软件是否开源？ <a class="header-anchor" href="#但我不是程序员-我为什么要关心一个软件是否开源" aria-label="Permalink to “但我不是程序员，我为什么要关心一个软件是否开源？”">​</a></h3><p>这是一个合理的问题。你不是一个软件开发者，只是一个普通的计算机用户。即使软件的源代码是可用的，你也不会理解程序的工作原理。</p><p>这很好。你不会明白，但有必要技能的人就会明白，这才是最重要的。</p><p>你可以这样想。也许你不会理解一份复杂的法律文件。但如果你有看文件的自由，并保留一份副本，你就可以咨询某个人，他可以检查文件中的法律陷阱。</p><p>换句话说，开源软件具有透明度。</p><h3 id="foss-与开源之间的区别是什么" tabindex="-1">FOSS 与开源之间的区别是什么？ <a class="header-anchor" href="#foss-与开源之间的区别是什么" aria-label="Permalink to “FOSS 与开源之间的区别是什么？”">​</a></h3><p>你会经常遇到 FOSS 和<ruby>开源<rt>Open Source</rt></ruby>的术语。它们经常被互换使用。</p><p>它们是同一件事吗？这很难用“是”和“不是”来回答。</p><p>你看，FOSS 中的“Free”一词让很多人感到困惑，因为人们错误地认为它是免费的。企业高管、高层和决策者往往会关注自由和开源中的“免费”。由于他们是商业人士，专注于为他们的公司赚钱，“自由”一词在采用 FOSS 原则时起到了威慑作用。</p>',10)),r("p",null,[t[14]||(t[14]=s("这就是为什么在上世纪 90 年代中期创立了一个名为",-1)),r("ruby",null,[o(l,{href:"https://opensource.org/"},{default:n(()=>[...t[11]||(t[11]=[s("开源促进会",-1)])]),_:1}),t[12]||(t[12]=r("rt",null,"Open Source Initiative",-1))]),t[15]||(t[15]=s("的新组织。他们从自由和开放源码软件中去掉了“自由”一词，并创建了自己的",-1)),o(l,{href:"https://opensource.org/osd"},{default:n(()=>[...t[13]||(t[13]=[s("开放源码的定义",-1)])]),_:1}),t[16]||(t[16]=s("，以及自己的一套许可证。",-1))]),t[43]||(t[43]=r("p",null,[s("“"),r("ruby",null,[s("开源"),r("rt",null,"Open Source")]),s("”一词在软件行业特别流行。高管们对开源更加适应。开源软件的采用迅速增长，我相信 “免费”一词的删除确实起到了作用。")],-1)),t[44]||(t[44]=r("h3",{id:"有问题吗",tabindex:"-1"},[s("有问题吗？ "),r("a",{class:"header-anchor",href:"#有问题吗","aria-label":"Permalink to “有问题吗？”"},"​")],-1)),r("p",null,[t[18]||(t[18]=s("这正如我在",-1)),o(l,{href:"https://itsfoss.com/what-is-linux-distribution/"},{default:n(()=>[...t[17]||(t[17]=[s("什么是 Linux 发行版",-1)])]),_:1}),t[19]||(t[19]=s("一文中所解释的那样，FOSS/开源的概念在 Linux 的发展和普及中起到了很大的作用。",-1))]),t[45]||(t[45]=r("p",null,"我试图在这篇黑话解释文章中用更简单的语言解释 FOSS 和开源的概念，而试图避免在细节或技术精度上做过多的阐述。",-1)),t[46]||(t[46]=r("p",null,"我希望你现在对这个话题有了更好的理解。如果你有问题或建议，欢迎留言并继续讨论。",-1)),t[47]||(t[47]=r("hr",null,null,-1)),r("p",null,[t[21]||(t[21]=s("via: ",-1)),o(l,{href:"https://itsfoss.com/what-is-foss/"},{default:n(()=>[...t[20]||(t[20]=[s("https://itsfoss.com/what-is-foss/",-1)])]),_:1})]),r("p",null,[t[26]||(t[26]=s("作者：",-1)),o(l,{href:"https://itsfoss.com/author/abhishek/"},{default:n(()=>[...t[22]||(t[22]=[s("Abhishek Prakash",-1)])]),_:1}),t[27]||(t[27]=s(" 选题：",-1)),o(l,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[23]||(t[23]=[s("lujun9972",-1)])]),_:1}),t[28]||(t[28]=s(" 译者：",-1)),o(l,{href:"https://github.com/wxy"},{default:n(()=>[...t[24]||(t[24]=[s("wxy",-1)])]),_:1}),t[29]||(t[29]=s(" 校对：",-1)),o(l,{href:"https://github.com/wxy"},{default:n(()=>[...t[25]||(t[25]=[s("wxy",-1)])]),_:1})]),r("p",null,[t[32]||(t[32]=s("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[30]||(t[30]=[s("LCTT",-1)])]),_:1}),t[33]||(t[33]=s(" 原创编译，",-1)),o(l,{href:"https://linux.cn/"},{default:n(()=>[...t[31]||(t[31]=[s("Linux中国",-1)])]),_:1}),t[34]||(t[34]=s(" 荣誉推出",-1))])])}const w=i(a,[["render",f]]);export{L as __pageData,w as default};
